'use client'
import { cn } from '@cascivo/core'
import type { HTMLAttributes } from 'react'
import styles from './segmented-control.module.css'

export interface SegmentedControlOption {
  label: string
  value: string
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
}

export interface SegmentedControlProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  options: SegmentedControlOption[]
  value: string
  onValueChange: (v: string) => void
  size?: 'sm' | 'md' | 'lg'
  /**
   * Accessible name for the group. Invisible — it names the `role="group"`, it renders
   * nothing.
   *
   * This component extended `HTMLAttributes` and nothing else, so it took the raw DOM
   * `aria-label` while every sibling in the catalog took `ariaLabel` — the one control in an
   * adopter's filter toolbar where the catalog spelling was a type error (2026-08-31 report
   * §21). Both spellings work now; the raw `aria-label` still wins if you pass both.
   */
  ariaLabel?: string
  /** Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered. */
  label?: string
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
}

export function SegmentedControl({
  options,
  value,
  onValueChange,
  size = 'md',
  disabled = false,
  ariaLabel,
  label,
  className,
  ...props
}: SegmentedControlProps) {
  function handleKeyDown(e: React.KeyboardEvent<HTMLButtonElement>, index: number) {
    const enabledOptions = options.filter((o) => !o.disabled)
    const currentEnabled = enabledOptions.findIndex((o) => o.value === options[index]?.value)
    if (e.key === 'ArrowRight') {
      e.preventDefault()
      const next = enabledOptions[(currentEnabled + 1) % enabledOptions.length]
      if (next) onValueChange(next.value)
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault()
      const prev =
        enabledOptions[(currentEnabled - 1 + enabledOptions.length) % enabledOptions.length]
      if (prev) onValueChange(prev.value)
    }
  }

  return (
    <div
      role="group"
      aria-label={ariaLabel ?? label}
      className={cn(styles['wrapper'], className)}
      data-size={size}
      data-disabled={disabled ? '' : undefined}
      {...props}
    >
      {options.map((opt, i) => (
        <button
          key={opt.value}
          type="button"
          role="radio"
          aria-checked={opt.value === value}
          data-selected={opt.value === value ? '' : undefined}
          data-size={size}
          className={styles['segment']}
          disabled={disabled || opt.disabled}
          onClick={() => {
            if (!opt.disabled) onValueChange(opt.value)
          }}
          onKeyDown={(e) => handleKeyDown(e, i)}
        >
          {opt.label}
        </button>
      ))}
    </div>
  )
}

@layer cascivo.component {
  .wrapper {
    display: inline-flex;
    gap: var(--cascivo-space-1);
    padding: var(--cascivo-space-1);
    background-color: var(--cascivo-color-bg-subtle);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-control);

    &[data-size='sm'] {
      --_seg-h: 1.75rem;
      --_seg-font: var(--cascivo-text-xs);
      --_seg-px: var(--cascivo-space-2);
    }

    &[data-size='md'] {
      --_seg-h: 2.25rem;
      --_seg-font: var(--cascivo-text-sm);
      --_seg-px: var(--cascivo-space-3);
    }

    &[data-size='lg'] {
      --_seg-h: 2.75rem;
      --_seg-font: var(--cascivo-text-base);
      --_seg-px: var(--cascivo-space-4);
    }

    &[data-disabled] {
      opacity: 0.5;
    }
  }

  .segment {
    height: var(--_seg-h, 2.25rem);
    padding-inline: var(--_seg-px, var(--cascivo-space-3));
    font-family: var(--cascivo-font-sans);
    font-size: var(--_seg-font, var(--cascivo-text-sm));
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text-subtle);
    background: none;
    border: none;
    border-radius: var(--cascivo-radius-item);
    cursor: pointer;
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      color var(--cascivo-duration-150) var(--cascivo-ease-out);
    white-space: nowrap;

    &:hover:not(:disabled):not([data-selected]) {
      color: var(--cascivo-color-text);
      background-color: rgb(from var(--cascivo-color-text) r g b / 0.05);
    }

    &:focus-visible {
      outline: 2px solid var(--cascivo-color-accent);
      outline-offset: 1px;
    }

    &[data-selected] {
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-surface);
      box-shadow: var(--cascivo-shadow-sm);
    }

    &:disabled {
      cursor: not-allowed;
      opacity: 0.5;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'SegmentedControl',
  description: 'Mutually exclusive toggle group',
  category: 'inputs',
  // Mutually exclusive selection through JS-only buttons — nothing can be selected without
  // JS.
  clientJs: 'required',
  states: ['idle', 'selected', 'disabled'],
  variants: [],
  sizes: ['sm', 'md', 'lg'],
  props: [
    {
      name: 'options',
      description: 'The selectable options.',
      type: 'SegmentedControlOption[]',
      required: true,
    },
    { name: 'value', description: 'The controlled value.', type: 'string', required: true },
    {
      name: 'onValueChange',
      description: 'Called with the new value when it changes.',
      type: '(v: string) => void',
      required: true,
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md' | 'lg'",
      required: false,
      default: 'md',
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      description:
        'Accessible name for the group. Invisible — it names the role="group" and renders nothing. The raw DOM `aria-label` still wins over this.',
      type: 'string',
      required: false,
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-bg-subtle',
    '--cascivo-color-border',
    '--cascivo-color-surface',
    '--cascivo-color-text',
    '--cascivo-radius-md',
    '--cascivo-radius-sm',
    '--cascivo-shadow-sm',
  ],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: ['ArrowLeft', 'ArrowRight'],
  },
  examples: [
    {
      title: 'Basic',
      code: `<SegmentedControl options={[{label:'Day',value:'day'},{label:'Week',value:'week'},{label:'Month',value:'month'}]} value="day" onValueChange={() => {}} />`,
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['form', 'toggle', 'group', 'segmented', 'input'],
  intent: {
    whenToUse: [
      'A compact inline single choice among a few mutually exclusive options (2–5) such as view modes or time ranges',
      'Switching between alternatives where all options should stay visible in a tight horizontal space',
    ],
    whenNotToUse: [
      'Switching between full panels of page content — use Tabs',
      'A single binary on/off state — use Toggle',
      'More options than comfortably fit inline, or options needing descriptions — use Select or RadioCard',
    ],
    antiPatterns: [
      {
        bad: 'Two <Button> elements toggling which is "active" via app state',
        good: '<SegmentedControl options={[{label:"Day",value:"day"},{label:"Week",value:"week"}]} value={range} onValueChange={setRange} />',
        why: 'A pair of buttons does not convey exclusive selection; SegmentedControl uses radio semantics with aria-checked and arrow-key navigation so the single-choice state is announced',
      },
    ],
    related: [
      {
        name: 'Toggle',
        relationship: 'alternative',
        reason: 'Use for a single binary on/off state, not a multi-option choice',
      },
      {
        name: 'Radio',
        relationship: 'alternative',
        reason: 'Use for a vertical or longer single-choice list with plain labels',
      },
      {
        name: 'Select',
        relationship: 'alternative',
        reason: 'Use when there are too many options to show inline',
      },
    ],
    a11yRationale:
      'Wraps role="radio" buttons in a role="group" with aria-checked marking the selected segment, and ArrowLeft/ArrowRight move selection across enabled segments (skipping disabled ones) so keyboard users get standard single-choice navigation.',
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Segment styling must resolve to the listed --cascivo-* tokens',
      },
      {
        area: 'option labels',
        level: 'flexible',
        note: 'option label and value are free, and individual options may be disabled',
      },
    ],
  },
}
